        "The intradermal BCG dose rises to **0.1 mL after 1 month of age**. [UIP MoHFW 2017]",
        "At **6, 10 and 14 weeks**: pentavalent (DPT + hepatitis B + Hib) **0.5 mL intramuscularly**. [UIP MoHFW 2017]",
        "At 6, 10 and 14 weeks: **OPV 2 drops orally** and **rotavirus vaccine 5 drops orally**. [UIP MoHFW 2017]",
        "Fractional IPV **0.1 mL intradermally at 6 and 14 weeks**. [UIP MoHFW 2017]",
        "PCV **0.5 mL intramuscularly at 6 and 14 weeks**. [UIP MoHFW 2017]",
        "At **9-12 months**: measles-rubella first dose **0.5 mL subcutaneously**, plus the PCV booster. [UIP MoHFW 2017]",
        "At 9-12 months: JE first dose in endemic districts. [UIP MoHFW 2017]",
        "At 9-12 months: **vitamin A first dose 100,000 IU (1 mL) orally**. [UIP MoHFW 2017]",
        "At **16-24 months**: MR second dose, DPT booster-1, OPV booster and JE second dose. [UIP MoHFW 2017]",
        "At 16-24 months: **vitamin A second dose 200,000 IU (2 mL)**. [UIP MoHFW 2017]",
        "Vitamin A is then repeated **6-monthly up to 5 years** - nine doses in all. [UIP MoHFW 2017]",
