        "A child falling from the median to **-2 SD over three months** is in trouble even while still within normal limits. [WHO 2006]",
        "Growth faltering: a fall across **two major centile lines**. [WHO 2006]",
        "Growth faltering: a flat or falling weight curve over **2-3 months**. [WHO 2006]",
