        "The strategy is **syndromic** and needs no diagnosis, laboratory or radiograph. [WHO IMCI 2014]",
        "It is designed for a worker with basic training and a wall chart. [WHO IMCI 2014]",
        "It saves lives by triage and by ensuring nobody with a danger sign is sent home. [WHO IMCI 2014]",
        "Every sick child contact follows **6 steps: assess, classify, identify treatment, treat, counsel the mother, follow up**. [IMNCI MoHFW]",
