        "NFHS-5: **7.3%** of under-fives had diarrhoea in the preceding 2 weeks. [NFHS-5 2019-21]",
        "NFHS-5: only about **six in ten** received ORS and **fewer than a third** received zinc. [NFHS-5 2019-21]",
        "The child dies of water and salt loss, not of the organism. [WHO 2005]",
