        "**The height of the temperature does not decide the classification** - danger signs, respiratory rate, skin, neck stiffness and behaviour do. [IMNCI MoHFW]",
        "**Fever with any general danger sign or a stiff neck is very severe febrile disease** - meningitis or sepsis until proved otherwise. [IMNCI MoHFW]",
        "Very severe febrile disease: first dose of **injection ampicillin 50 mg/kg plus gentamicin 7.5 mg/kg** before referral, because delay kills. [IMNCI MoHFW]",
