        "**Every fever in a malaria area is tested by rapid diagnostic test or microscopy the same day** - treatment is by species, never presumptive. [NVBDCP 2013]",
        "A negative malaria test with no runny nose, no measles and no other cause is fever with no focus - **review in 2 days**. [IMNCI MoHFW]",
        "**Fever every day for more than 7 days is referred** - enteric fever, tuberculosis, urinary infection and Kawasaki disease hide in that group. [IMNCI MoHFW]",
        "**Measles is fever with a generalised maculopapular rash plus one of cough, runny nose or red eyes** - the rash alone is not enough. [IMNCI MoHFW]",
        "Every child with measles gets **vitamin A on days 1 and 2**: 100,000 IU at 6-12 months, 200,000 IU above 12 months. [IMNCI MoHFW]",
        "**Corneal clouding, deep or extensive mouth ulcers or any danger sign make it severe complicated measles** - refer the same day. [IMNCI MoHFW]",
        "Uncomplicated measles: **pus from the eye gets tetracycline eye ointment and mouth ulcers get gentian violet**. [IMNCI MoHFW]",
        "**Any fever in an infant under 2 months is a danger sign in its own right** - about one in ten has bacteraemia, meningitis or urinary infection. [IMNCI MoHFW]",
        "The febrile young infant looks well in most of those cases, so follow the young infant chart: **first dose of antibiotic and refer**. [IMNCI MoHFW]",
        "Ask for cough, ear pain, diarrhoea, dysuria, rash, joint swelling, a limp or a recent injection - **the focus is found by history first**. [IMNCI MoHFW]",
        "**Examine every febrile child undressed** - ears, throat, chest, abdomen, skin, fontanelle, neck and joints in one pass. [IMNCI MoHFW]",
        "**The commonest missed foci are the ear, the urine and the bone** - each stays silent unless specifically sought. [IMNCI MoHFW]",
