        "**In a well child of 3-36 months with fever and no focus, urinary tract infection is the commonest occult bacterial infection.** [Nelson 22e]",
        "Risk is highest in girls, uncircumcised boys, and **any child with fever over 39 degrees C for more than 2 days**. [Nelson 22e]",
        "**A clean-catch urine for dipstick, microscopy and culture is the one investigation that must be done** in fever without a focus. [Nelson 22e]",
