        "**Anemia Mukt Bharat (2018) is a 6x6x6 strategy: six target groups, six interventions and six institutional mechanisms.** [Anemia Mukt Bharat 2018]",
        "**Its target is a fall of 3 percentage points in anaemia prevalence every year** across the life cycle. [Anemia Mukt Bharat 2018]",
        "The six beneficiaries: **6-59 months, 5-9 years, 10-19 years, women 20-49 years, pregnant and lactating women**. [Anemia Mukt Bharat 2018]",
