        "At 10-19 years: **one blue tablet weekly, 60 mg iron with 500 micrograms folic acid**. [Anemia Mukt Bharat 2018]",
        "That adolescent tablet is the **Weekly Iron and Folic Acid Supplementation (WIFS) scheme**, given in school on a fixed weekday. [Anemia Mukt Bharat 2018]",
        "Non-pregnant women 20-49 years: **one red tablet weekly, 60 mg iron with 500 micrograms folic acid**. [Anemia Mukt Bharat 2018]",
        "In pregnancy: **60 mg iron and 500 micrograms folic acid daily for 180 days from the second trimester, and 180 days after delivery**. [Anemia Mukt Bharat 2018]",
        "Intervention 2 is deworming: **albendazole 400 mg twice a year from 1 to 19 years, with 200 mg at 12-23 months**. [Anemia Mukt Bharat 2018]",
        "Pregnancy gets **a single deworming dose in the second trimester**, never the first. [Anemia Mukt Bharat 2018]",
        "Intervention 3 is **year-round behaviour change communication, the Solid Body Smart Mind campaign**. [Anemia Mukt Bharat 2018]",
