        "Dental extraction manipulates gingival tissue, so this child needs a single dose of antibiotic prophylaxis - amoxicillin 50 mg/kg orally, maximum 2 g, 30-60 minutes before the procedure - together with specific precautions against a hypercyanotic spell, against bleeding and against paradoxical air embolism, and a plan for definitive cardiac repair.",
