            "**Secondary erythrocytosis with a haematocrit above 65% raises the thrombosis risk if the child is fasted or dehydrated** - keep clear fluids running. [Nelson 22e]",
            "**Relative iron deficiency, a microcytic normal-looking haemoglobin, worsens spells and increases stroke risk** and is corrected before elective work. [Nelson 22e]",
