        "The disappearing murmur confirms that almost no blood is crossing the right ventricular outflow tract, and after position, oxygen, morphine and volume the next steps are sodium bicarbonate for the acidosis and then a beta blocker to relieve the infundibular spasm - propranolol 0.1 mg/kg (range 0.05-0.2) by slow intravenous injection over 5-10 minutes with ECG monitoring, repeatable once after 15 minutes; sodium bicarbonate 1-2 mEq/kg and then a pure vasoconstrictor such as phenylephrine follow if it persists. Adrenaline and any other inotrope are actively harmful: increasing contractility tightens the infundibular spasm and the beta-2 effect lowers systemic vascular resistance, both of which widen the right-to-left shunt. Digoxin does the same and is contraindicated in a spell. Frusemide reduces preload, which is the opposite of what a spell needs - the right ventricle must be filled, not emptied. Salbutamol is a vasodilator and bronchodilator and would worsen the shunt; this is not bronchospasm.",
