        "**Uncomplicated primary monosymptomatic enuresis in a well child needs no investigation beyond a urine dipstick and a bladder and bowel diary.** [NICE CG111 2010]",
        "**No ultrasound, no blood tests, no imaging** - over-investigating a maturational delay medicalises it and delays the treatment that works. [NICE CG111 2010]",
