        "**Add specific gravity or a first-morning osmolality for concentrating capacity** - the cheapest test for a concentrating defect. [ICCS 2020]",
        "**NICE reserves urinalysis for bedwetting that began in the last days or weeks, daytime symptoms, ill health, or suspected infection or diabetes.** [NICE CG111 2010]",
        "**In Indian practice a dipstick in every child is cheap and catches the diabetic** - a defensible departure from the NICE position. [IAP 2023]",
        "**Send a urine culture only if symptoms or the dipstick suggest infection** - asymptomatic bacteriuria in a bedwetting child is not treated. [ICCS 2020]",
        "**Check capillary or venous blood glucose whenever there is polyuria, polydipsia, weight loss, an unwell child or an abrupt secondary onset.** [Nelson 22e]",
        "**New type 1 diabetes classically presents as a previously dry child who suddenly wets the bed** - missing it is the one genuinely dangerous error here. [Nelson 22e]",
        "**The bladder and bowel diary is the investigation of the topic and does more than any test.** [ICCS 2020]",
        "**Record 48-72 hours of normal days with the time and volume of every void and every drink.** [ICCS 2020]",
        "**Record at least seven consecutive nights of wet or dry, with the number of wet episodes each night.** [ICCS 2020]",
        "**Weigh the nappy or pad before and after, taking 1 g as 1 mL, and add the first morning void** - that is the overnight output. [ICCS 2020]",
        "**Add bowel movements with Bristol stool type, and urgency or wetting episodes** - a nearly empty bowel chart is itself a finding. [ICCS 2020]",
        "**Compute expected bladder capacity = (age + 1) x 30 mL and read the diary against it.** [ICCS 2020]",
        "**A maximum voided volume, excluding the first morning void, below 65% of expected capacity means a small functional bladder.** [ICCS 2020]",
        "**Overnight output above 130% of expected capacity means nocturnal polyuria**, and polyuria with a normal capacity predicts a desmopressin response. [ICCS 2020]",
