        "**The melt 120/240 microgram is bioequivalent to the tablet 200/400 microgram** and is preferred for adherence and for being less affected by food. [ICCS 2020]",
        "**Intranasal desmopressin must not be used for enuresis** - it was withdrawn for this indication after deaths from hyponatraemia. [ICCS 2020]",
