        "**Follow up on the wet-night count, not on impressions** - the family keeps the same chart used at baseline. [ICCS 2020]",
        "**Review an alarm at 4 weeks for early signs of response and continue to 14 consecutive dry nights or up to 3 months.** [NICE CG111 2010]",
