        "**ICCS categories: no response is a fall of under 50% in wet nights, partial response 50-99%, complete response 100% or fewer than one wet night a month.** [ICCS 2020]",
        "**Relapse is more than one wet night a month after a complete response**; continued success is six months without relapse, complete success two years. [ICCS 2020]",
        "**A treatment is not a failure until used correctly for an adequate period - at least 6-8 weeks for an alarm, 4 weeks at the higher desmopressin dose.** [ICCS 2020]",
