        "**Say the prognosis out loud: about 15% become dry each year without treatment, and fewer than 1-2% carry enuresis into adult life.** [ICCS 2020]",
        "**Persistence is predicted by wetting every night or more than once a night, non-monosymptomatic disease, a strong family history and neurodevelopmental comorbidity.** [ICCS 2020]",
        "**Spontaneous resolution is not a reason to withhold treatment from a distressed child** - it is a reason to be honest about what treatment adds. [NICE CG111 2010]",
