        "**The adolescent is the small residual group, often with severe every-night wetting and a family history** - ask directly, because he may be hiding it entirely. [ICCS 2020]",
        "**Enuresis is a recognised trigger for physical punishment and for abuse in vulnerable households** - one more reason to say explicitly that the child is not to blame. [NICE CG111 2010]",
        "**Refer any child under five with daytime symptoms or a suspected organic cause.** [NICE CG111 2010]",
        "**Refer secondary enuresis with red flags, or without an obvious psychosocial explanation.** [NICE CG111 2010]",
        "**Refer suspected neurological or structural disease: sacral stigma, abnormal gait or limb signs, poor stream, palpable bladder, recurrent febrile urinary infection.** [NICE CG111 2010]",
