  pearls: [
    "**Say it in front of the child: bedwetting is not his fault, he is not lazy or dirty, and punishing him for it makes it worse.** The sentence is therapeutic, it is examinable, and it is the one the family remembers.",
    "**The first classifying question is 'has this child ever been dry at night for six months?' and the second is 'any daytime symptoms?'** Those two answers give primary or secondary, monosymptomatic or non-monosymptomatic, and they determine everything that follows.",
    "**Treat constipation first.** It is present in 30-50%, the parent never volunteers it, the child never complains of it, and clearing a loaded rectum with a macrogol alone dries a significant minority of beds without any enuresis-specific treatment.",
    "**A previously dry child who suddenly starts wetting the bed has type 1 diabetes until a glucose says otherwise.** It is the one dangerous diagnosis in an otherwise benign topic.",
    "**Reward effort, never dry nights.** A dry night is not under the child's control, so rewarding it quietly re-attaches the blame the consultation has just removed - reward drinking properly, voiding before bed, helping change the sheets and using the alarm.",
    "**Expected bladder capacity in mL = (age in years + 1) x 30, ceiling about 390 mL.** Overnight output above 130% of EBC is nocturnal polyuria (a desmopressin responder); maximum voided volume below 65% of EBC is a small bladder (an antimuscarinic candidate). The diary, not the imaging, gives the mechanism.",
    "**Do not lift or wake the child to void as treatment** - it produces dry sheets without producing continence and may reinforce voiding while asleep. An alarm the child has to respond to is a different thing entirely.",
    "**The whole safety of desmopressin is one sentence: no more than about 240 mL of fluid from one hour before the dose to eight hours after, and skip the dose on any day with vomiting, diarrhoea, fever or heavy exertion.** Hyponatraemic seizures in this condition are always avoidable.",
    "**The alarm is the only treatment that cures rather than masks**, with the lowest relapse rate of any option - but it needs 6-8 weeks before it can be called a failure, nightly use without exception, and a family that is not already angry and exhausted.",
    "**Where the guidelines genuinely differ, say so:** NICE puts the alarm first and desmopressin second (reserving desmopressin for when speed matters or an alarm is unsuitable, and generally from 7 years), while the ICCS treats alarm and desmopressin as equal first-line choices decided by the mechanism on the diary and the family's circumstances. Both are defensible in an answer if the reasoning is stated.",
  ],
