            "**Also overactive bladder and dysfunctional voiding, and chronic kidney disease with a concentrating defect.** [Nelson 22e]",
            "**Constipation with rectal loading is present in 30-50%** - it compresses the bladder, cuts capacity and provokes overactivity, and is the most rewarding cause to treat. [ICCS 2020]",
