            "**Haematological and infective: sickle cell disease or trait with hyposthenuria, and threadworm infestation.** [Nelson 22e]",
            "**Psychosocial: a new sibling, bereavement, parental separation, migration, bullying, school change, and child sexual abuse.** [NICE CG111 2010]",
            "**Iatrogenic: valproate, lithium, clozapine, theophylline, diuretics and caffeine.** [Nelson 22e]",
