            "**Uroflowmetry with EMG for dysfunctional voiding, and MRI of the lumbosacral spine for a sacral stigma or neurological sign.** [ICCS 2020]",
            "**Polysomnography or ENT referral for snoring, and creatinine with early morning urine osmolality where renal disease is suspected.** [Nelson 22e]",
