            "**Never the intranasal preparation** - it was withdrawn for enuresis after deaths from hyponatraemia. [ICCS 2020]",
            "**Desmopressin suits documented nocturnal polyuria, rapid or short-term cover - a school trip, camp or sleepover - and a failed or impractical alarm.** [NICE CG111 2010]",
            "**The fluid rule is essential: no more than 240 mL from 1 hour before to 8 hours after the dose**, and omit it during vomiting, diarrhoea or fever. [ICCS 2020]",
            "**Hyponatraemia with headache, vomiting, drowsiness and convulsions is the serious adverse effect**, and it comes from drinking against the drug. [ICCS 2020]",
