            "**Add an antimuscarinic for the non-monosymptomatic child with an overactive bladder, or the desmopressin non-responder with a small bladder.** [ICCS 2020]",
            "**Oxybutynin 2.5-5 mg at bedtime, tolterodine 2 mg or solifenacin 5 mg, usually combined with desmopressin**, with the post-void residual checked before and during. [ICCS 2020]",
