            "**Dispense small quantities, insist on safe storage, review 3-monthly and withdraw gradually.** [ICCS 2020]",
            "**Combination therapy - alarm plus desmopressin, or desmopressin plus an antimuscarinic - salvages many refractory cases.** [ICCS 2020]",
            "**Guidance differs: NICE places the alarm first, while ICCS treats alarm and desmopressin as equal first-line options** chosen on the diary and the family. [ICCS 2020]",
