        "Secondary enuresis of recent onset with polyuria, polydipsia and weight loss is new type 1 diabetes mellitus until proved otherwise, and the immediate test is a urine dipstick for glucose and ketones with a blood glucose - a delay here ends in ketoacidosis. Urine culture is reasonable in secondary enuresis in general, but there is no dysuria, frequency of a urinary-infection pattern or fever, and it would not detect the dangerous diagnosis. Ultrasound would be normal and answers a structural question that has not been raised. MRI of the spine is for sacral cutaneous stigmata, abnormal gait or lower limb neurological signs, none of which is described. A bladder diary is the key investigation in ordinary monosymptomatic enuresis and should indeed be done, but it characterises the mechanism rather than excluding the emergency, and it takes days.",
