      stem: "A 3-week-old term, exclusively breastfed, thriving infant has white curd-like plaques on the tongue and buccal mucosa for 4 days. The plaques come off on gentle scraping leaving a red, slightly bleeding base. He is afebrile, active and gaining weight, and his mother has no nipple pain. What is the most appropriate first-line treatment?",
